package net.civeira.phylax.feature.identity.tenantconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantconfig.domain.TenantConfig;
import net.civeira.phylax.feature.identity.tenantconfig.domain.valueobject.WebauthnRpNameVO;

class WebauthnRpNameValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of webauthn rp name of tenant config")
  void test_webauthn_rp_name_value_holder_assign_plain_value() {
    Object holder = new Object();
    WebauthnRpNameValueHolder<Object> value = new WebauthnRpNameValueHolder<>(holder);
    Assertions.assertSame(holder, value.webauthnRpName("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getWebauthnRpNameValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getWebauthnRpName().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.webauthnRpNameNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getWebauthnRpNameValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getWebauthnRpName().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of webauthn rp name of tenant config")
  void test_webauthn_rp_name_value_holder_assign_value_object() {
    Object holder = new Object();
    WebauthnRpNameValueHolder<Object> value = new WebauthnRpNameValueHolder<>(holder);
    WebauthnRpNameVO vo = WebauthnRpNameVO.from("one");
    Assertions.assertFalse(value.getWebauthnRpNameValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.webauthnRpName(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getWebauthnRpNameValue().orElseThrow());
    Assertions.assertSame(holder, value.webauthnRpName(Optional.empty()));
    Assertions.assertFalse(value.getWebauthnRpNameValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.webauthnRpName(Optional.of(vo)));
    Assertions.assertSame(vo, value.getWebauthnRpNameValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of webauthn rp name of tenant config against the original")
  void test_webauthn_rp_name_value_holder_read() {
    Object holder = new Object();
    WebauthnRpNameValueHolder<Object> value = new WebauthnRpNameValueHolder<>(holder);
    WebauthnRpNameVO vo = WebauthnRpNameVO.from("one");
    WebauthnRpNameVO other = WebauthnRpNameVO.from("one");
    TenantConfig original = Mockito.mock(TenantConfig.class);
    Mockito.when(original.getWebauthnRpNameValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readWebauthnRpName(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readWebauthnRpName(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.webauthnRpName(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readWebauthnRpName(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readWebauthnRpName(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of webauthn rp name of tenant config")
  void test_webauthn_rp_name_value_holder_unset() {
    Object holder = new Object();
    WebauthnRpNameValueHolder<Object> value = new WebauthnRpNameValueHolder<>(holder);
    WebauthnRpNameVO vo = WebauthnRpNameVO.from("one");
    value.webauthnRpName(vo);
    Assertions.assertSame(holder, value.unsetWebauthnRpNameIfMatches("webauthnRpName_other"));
    Assertions.assertTrue(value.getWebauthnRpNameValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetWebauthnRpNameIfMatches("webauthnRpName"));
    Assertions.assertFalse(value.getWebauthnRpNameValue().isPresent(),
        "The field name must clear the value");
    value.webauthnRpName(vo);
    Assertions.assertSame(holder, value.unsetWebauthnRpName());
    Assertions.assertFalse(value.getWebauthnRpNameValue().isPresent(),
        "Unset must clear the value");
  }
}
